import requests
import json
import time
import sys

# 引数からYouTube URLを取得（指定がなければデフォルト）
if len(sys.argv) > 1:
    youtube_url = sys.argv[1]
else:
    youtube_url = "https://www.youtube.com/watch?v=S7-Lw14P5sQ"

headers = {
    "Content-Type": "application/json",
    "Accept": "application/json, text/javascript, */*; q=0.01",
    "X-Lang-Code": "ja",
    "X-Requested-With": "XMLHttpRequest",
    "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 16_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.6 Mobile/15E148 Safari/604.1"
}

# 1. タスク作成リクエスト
create_task_url = "https://airmore.ai/ja/wp-json/airmore/v1/video-download/formats"

payload = {
    "youtube_url": youtube_url,
    "device_info": {
        "canvas": "data:image/png;base64,"
    }
}

print(f"[1] タスクを作成中... URL: {youtube_url}")
res1 = requests.post(create_task_url, headers=headers, json=payload)
data1 = res1.json()

if not data1.get("success"):
    print("エラー: タスクの作成に失敗しました。")
    print(data1)
    sys.exit()

task_id = data1.get("task_id")
wait_sec = data1.get("estimated_processing_seconds", 10)
print(f"-> タスクID取得完了: {task_id}")
print(f"-> 処理完了まで約 {wait_sec} 秒待機します...")

# 2. 処理完了まで待機
time.sleep(wait_sec + 2)

# 3. 結果の取得
status_url = f"https://airmore.ai/ja/wp-json/airmore/v1/video-download/formats/status/{task_id}"

print("[2] 解析結果を取得中...")
res2 = requests.get(status_url, headers=headers)
data2 = res2.json()

if data2.get("status") == "completed":
    print("\n" + "="*50)
    print(f"タイトル: {data2.get('video_title')}")
    print(f"投稿者  : {data2.get('uploader')}")
    print("="*50)
    print("\nダウンロードURL一覧:")
    
    for fmt in data2.get("formats", []):
        note = fmt.get("format_note", "Audio")
        ext = fmt.get("ext")
        url = fmt.get("url")
        print(f"\n[{note} / {ext}]")
        print(url)
else:
    print("まだ処理が完了していません。もう一度実行するか、待機時間を増やしてください。")
    print(data2)
